function serializeFacets(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError("rows must be an array");
  }

  const pairs = [];

  for (let i = 0; i < rows.length; i++) {
    if (!Object.prototype.hasOwnProperty.call(rows, i)) {
      throw new TypeError("rows must be dense");
    }

    const row = rows[i];
    if (
      row === null ||
      typeof row !== "object" ||
      (Object.getPrototypeOf(row) !== Object.prototype &&
        Object.getPrototypeOf(row) !== null)
    ) {
      throw new TypeError("invalid row");
    }

    const name = row.name;
    const values = row.values;

    if (typeof name !== "string" || !Array.isArray(values)) {
      throw new TypeError("invalid row fields");
    }

    const encodedName = encodeRFC3986(name);

    for (let j = 0; j < values.length; j++) {
      if (!Object.prototype.hasOwnProperty.call(values, j)) {
        throw new TypeError("values must be dense");
      }
      if (typeof values[j] !== "string") {
        throw new TypeError("values must contain strings");
      }

      pairs.push([encodedName, encodeRFC3986(values[j])]);
    }
  }

  pairs.sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    if (a[1] < b[1]) return -1;
    if (a[1] > b[1]) return 1;
    return 0;
  });

  return pairs.map(pair => pair[0] + "=" + pair[1]).join("&");
}

function encodeRFC3986(value) {
  const hex = "0123456789ABCDEF";
  let result = "";

  for (let i = 0; i < value.length; i++) {
    let codePoint = value.charCodeAt(i);

    if (codePoint >= 0xD800 && codePoint <= 0xDBFF) {
      if (i + 1 >= value.length) {
        throw new URIError("Unpaired surrogate");
      }

      const low = value.charCodeAt(++i);
      if (low < 0xDC00 || low > 0xDFFF) {
        throw new URIError("Unpaired surrogate");
      }

      codePoint =
        0x10000 + ((codePoint - 0xD800) << 10) + (low - 0xDC00);
    } else if (codePoint >= 0xDC00 && codePoint <= 0xDFFF) {
      throw new URIError("Unpaired surrogate");
    }

    if (
      codePoint >= 0x41 && codePoint <= 0x5A ||
      codePoint >= 0x61 && codePoint <= 0x7A ||
      codePoint >= 0x30 && codePoint <= 0x39 ||
      codePoint === 0x2D ||
      codePoint === 0x2E ||
      codePoint === 0x5F ||
      codePoint === 0x7E
    ) {
      result += String.fromCharCode(codePoint);
    } else if (codePoint <= 0x7F) {
      result += "%" + hex[codePoint >> 4] + hex[codePoint & 0x0F];
    } else if (codePoint <= 0x7FF) {
      result += percentByte(0xC0 | (codePoint >> 6), hex);
      result += percentByte(0x80 | (codePoint & 0x3F), hex);
    } else if (codePoint <= 0xFFFF) {
      result += percentByte(0xE0 | (codePoint >> 12), hex);
      result += percentByte(0x80 | ((codePoint >> 6) & 0x3F), hex);
      result += percentByte(0x80 | (codePoint & 0x3F), hex);
    } else {
      result += percentByte(0xF0 | (codePoint >> 18), hex);
      result += percentByte(0x80 | ((codePoint >> 12) & 0x3F), hex);
      result += percentByte(0x80 | ((codePoint >> 6) & 0x3F), hex);
      result += percentByte(0x80 | (codePoint & 0x3F), hex);
    }
  }

  return result;
}

function percentByte(byte, hex) {
  return "%" + hex[byte >> 4] + hex[byte & 0x0F];
}
